    if ask == 'the_three_limits_for_himself':
        ink('17:16-17', '"ONLY HE SHALL NOT MULTIPLY HORSES FOR HIMSELF, nor return the people to Egypt in order to multiply horse, since the LORD said to you: you shall not return that way again; AND HE SHALL NOT MULTIPLY WIVES FOR HIMSELF, that his heart turn not; AND SILVER AND GOLD HE SHALL NOT MULTIPLY GREATLY FOR HIMSELF" — "for himself" three times %s; "horses" and "horse" %s; 8:13\'s silver and gold the twin (shared %d — good_land)' % ([(v, x) for v in (16, 17) for x in W(17, v) if x == 'לו'], [x for x in W(17, 16) if x in ('סוסים', 'סוס')], TWIN['17:17 vs 8:13']))
        move('the Sifrei 158:1-4, 159:1-4 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew at 161:1); MISHNAH SANHEDRIN 2:4 (read whole at the design — THE EXAM ROW); cold_run_good_land (CALL) — GL.DATA[the_kings_law_tokens] = %s' % (str(GL_TOK['value'])[:70],), "'FOR HIMSELF' SPLITS EACH LIMIT — for himself not, for his chariots and horsemen he may (158:1 — Sanhedrin 2:4: enough for his chariot); 'horse' the idle beast (158:2); EVEN ONE IDLE HORSE ENOUGH TO RETURN THE PEOPLE TO EGYPT (158:3); the a fortiori to every land (158:4 — I1); 'wives' — BUT EIGHTEEN (159:1 — Sanhedrin 2:4); R. Judah: he may multiply provided they do not turn his heart; R. Simeon: even one who turns his heart, and 'he shall not multiply' even Abigail and her companions (159:2-3 — THREE ARMS on the Mishnah's own line); 'silver and gold' — for himself not, for the army he may (159:4 — Sanhedrin 2:4: the soldiers' pay); DAVID KEPT IT AND SOLOMON CHANGED IT (1 Chronicles 22:14, 1 Kings 10:27 — the run's future case); 'since the LORD said to you' A RECEIPT BEHIND — Exodus 14:13's clause inside the tape's Exodus 14 scene (no own line; Sukkah 51b's reading not read)")
        dat("THE WRITES horses_multiplying_barred, return_to_egypt_barred, wives_multiplying_barred, silver_and_gold_multiplying_barred — BLOCKS on israel_people at the chapters' own day (DI2); THE PARAMETER the_three_limits (Sanhedrin 2:4: eighteen wives with three arms, the chariot's horses, the soldiers' pay; the idle horse); Solomon the readback's future exercise; the exam's person the king who keeps horses beyond his chariot — barred from it")
        return out("the three limits for himself (17:16-17) — the chariot's horses and the army's treasury allowed, the idle horse, eighteen wives or the heart or Abigail, the soldiers' pay, David and Solomon (the Sifrei 158:1-159:4 = Mishnah Sanhedrin 2:4 — the exam row read whole; good_land's twin by CALL): THE WRITES horses_multiplying_barred, return_to_egypt_barred, wives_multiplying_barred, silver_and_gold_multiplying_barred, BLOCKS on Israel at the chapters' own day; the king who keeps horses beyond his chariot barred from it", ['horses_multiplying_barred', 'return_to_egypt_barred', 'wives_multiplying_barred', 'silver_and_gold_multiplying_barred'])
    if ask == 'the_copy_of_the_law':
        ink('17:18-19', '"and when he sits on the throne of his kingdom, HE SHALL WRITE FOR HIMSELF A COPY OF THIS LAW ON A BOOK from before the priests the Levites; and it shall be with him and he shall read in it ALL THE DAYS OF HIS LIFE" — "a copy of this law" %s; "all the days of his life" %s' % ([x for x in W(17, 18) if x in ('משנה', 'התורה')], [x for x in W(17, 19) if x in ('כל', 'ימי', 'חייו')]))
